t.script:
var consignmentEnabled = ;
var partnerActionId = ;

function rpc(url, params) {
    return fetch(url, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params, id: Date.now()}),
        credentials: 'same-origin',
    }).then(function(r) { return r.json(); }).then(function(d) { return d.result; });
}

function escapeHtml(text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
}

/* ===== View Navigation ===== */
function showSelector() {
    document.getElementById('tcg_selector_view').style.display = '';
    document.getElementById('tcg_stock_view').classList.remove('active');
    document.getElementById('tcg_consignment_view').classList.remove('active');
    loadRecentAdditions();
}

function showStockForm() {
    document.getElementById('tcg_selector_view').style.display = 'none';
    document.getElementById('tcg_stock_view').classList.add('active');
    document.getElementById('tcg_consignment_view').classList.remove('active');
    loadEmployees();
    loadOpenPOs();
}

function showConsignmentForm() {
    document.getElementById('tcg_selector_view').style.display = 'none';
    document.getElementById('tcg_stock_view').classList.remove('active');
    document.getElementById('tcg_consignment_view').classList.add('active');
    loadEmployees();
}

/* ===== Load Employees ===== */
function loadEmployees() {
    rpc('/tcg/aankoop/get_employees', {}).then(function(employees) {
        ['tcg_stock_employee', 'tcg_cons_employee'].forEach(function(selId) {
            var sel = document.getElementById(selId);
            var curVal = sel.value;
            sel.innerHTML = '';
            var defOpt = document.createElement('option');
            defOpt.value = '';
            defOpt.textContent = 'Select employee...';
            sel.appendChild(defOpt);
            (employees || []).forEach(function(e) {
                var opt = document.createElement('option');
                opt.value = e.id;
                opt.textContent = e.name + (e.department_name ? ' - ' + e.department_name : '');
                if (String(e.id) === curVal) opt.selected = true;
                sel.appendChild(opt);
            });
        });
    });
}

/* ===== Load Open POs ===== */
function loadOpenPOs() {
    rpc('/tcg/get_open_purchase_orders', {}).then(function(pos) {
        var sel = document.getElementById('tcg_stock_po');
        sel.innerHTML = '';
        var defOpt = document.createElement('option');
        defOpt.value = '';
        defOpt.textContent = 'No PO';
        sel.appendChild(defOpt);
        (pos || []).forEach(function(po) {
            var opt = document.createElement('option');
            opt.value = po.id;
            opt.textContent = po.name + ' \u2014 ' + po.partner_name + ' (' + po.remaining_qty + '/' + po.total_qty + ' remaining)';
            sel.appendChild(opt);
        });
        updateStockTile();
    });
}

/* ===== SuperTCG Stock Tile ===== */
var stockCateg = document.getElementById('tcg_stock_categ');
var stockLoc = document.getElementById('tcg_stock_location');
var stockEmp = document.getElementById('tcg_stock_employee');
var stockPo = document.getElementById('tcg_stock_po');
var stockTile = document.getElementById('tcg_stock_tile');

function updateStockTile() {
    var c = stockCateg.value;
    var l = stockLoc.value;
    var e = stockEmp.value;
    if (c && l && e) {
        stockTile.classList.remove('tcg-action-tile-disabled');
        var url = '/web#action=supertcg_products.action_tcg_card_form'
            + '&categ_id=' + c
            + '&location_id=' + l
            + '&employee_id=' + e
            + '&employee_name=' + encodeURIComponent(stockEmp.options[stockEmp.selectedIndex].text);
        var poVal = stockPo.value;
        if (poVal) {
            url += '&po_id=' + poVal;
        }
        stockTile.href = url;
    } else {
        stockTile.classList.add('tcg-action-tile-disabled');
        stockTile.href = '#';
    }
}
stockCateg.addEventListener('change', updateStockTile);
stockLoc.addEventListener('change', updateStockTile);
stockEmp.addEventListener('change', updateStockTile);
stockPo.addEventListener('change', updateStockTile);

/* ===== Consignment Partner Autocomplete ===== */
var consPartnerInput = document.getElementById('tcg_cons_partner_input');
var consPartnerDropdown = document.getElementById('tcg_cons_partner_dropdown');
var consPartnerIdField = document.getElementById('tcg_cons_partner_id');
var consSearchTimer = null;
var consActiveIndex = -1;
var consAbortController = null;

consPartnerInput.addEventListener('input', function() {
    var term = this.value.trim();
    if (consSearchTimer) clearTimeout(consSearchTimer);
    if (consAbortController) { try { consAbortController.abort(); } catch(e){} }
    if (term.length < 2) { consPartnerDropdown.classList.remove('open'); return; }
    consSearchTimer = setTimeout(function() {
        consAbortController = new AbortController();
        fetch('/tcg/aankoop/search_partner', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {term: term}, id: Date.now()}),
            credentials: 'same-origin',
            signal: consAbortController.signal,
        }).then(function(r) { return r.json(); }).then(function(d) {
            var results = d.result;
            consActiveIndex = -1;
            consPartnerDropdown.innerHTML = '';
            results.forEach(function(r) {
                var div = document.createElement('div');
                div.className = 'tcg-autocomplete-item';
                div.setAttribute('data-id', r.id);
                div.setAttribute('data-name', r.name);
                div.textContent = r.name;
                div.addEventListener('click', function() { selectConsPartner(r.id, r.name); });
                consPartnerDropdown.appendChild(div);
            });
            var createDiv = document.createElement('div');
            createDiv.className = 'tcg-autocomplete-create';
            createDiv.textContent = 'Create new partner in Odoo \u2197';
            createDiv.addEventListener('click', function() {
                window.open('/odoo/action-' + partnerActionId + '/new', '_blank');
                consPartnerDropdown.classList.remove('open');
            });
            consPartnerDropdown.appendChild(createDiv);
            consPartnerDropdown.classList.add('open');
        }).catch(function(err) {
            if (err.name !== 'AbortError') {
                consPartnerDropdown.classList.remove('open');
            }
        });
    }, 300);
});

consPartnerInput.addEventListener('keydown', function(ev) {
    var items = consPartnerDropdown.querySelectorAll('.tcg-autocomplete-item');
    if (ev.key === 'ArrowDown') { ev.preventDefault(); consActiveIndex = Math.min(consActiveIndex + 1, items.length - 1); highlightConsItems(items); }
    else if (ev.key === 'ArrowUp') { ev.preventDefault(); consActiveIndex = Math.max(consActiveIndex - 1, 0); highlightConsItems(items); }
    else if (ev.key === 'Enter' && consActiveIndex >= 0 && items[consActiveIndex]) { ev.preventDefault(); items[consActiveIndex].click(); }
    else if (ev.key === 'Escape') { consPartnerDropdown.classList.remove('open'); }
});

function highlightConsItems(items) {
    items.forEach(function(it, i) { it.classList.toggle('active', i === consActiveIndex); });
}

function selectConsPartner(id, name) {
    consPartnerIdField.value = id;
    consPartnerInput.value = '';
    consPartnerInput.style.display = 'none';
    consPartnerDropdown.classList.remove('open');
    document.getElementById('tcg_cons_partner_selected_name').textContent = name;
    document.getElementById('tcg_cons_partner_selected').classList.add('show');
    var editLink = document.getElementById('tcg_cons_partner_edit_link');
    editLink.href = '/odoo/action-' + partnerActionId + '/' + id;
    editLink.style.display = 'inline';
    updateConsignmentTile();
}

function clearConsPartner() {
    consPartnerIdField.value = '';
    document.getElementById('tcg_cons_partner_selected').classList.remove('show');
    document.getElementById('tcg_cons_partner_edit_link').style.display = 'none';
    consPartnerInput.style.display = '';
    consPartnerInput.value = '';
    consPartnerInput.focus();
    updateConsignmentTile();
}

document.addEventListener('click', function(ev) {
    if (!document.getElementById('tcg_cons_partner_ac').contains(ev.target)) {
        consPartnerDropdown.classList.remove('open');
    }
});

/* ===== Consignment Tile ===== */
var consCateg = document.getElementById('tcg_cons_categ');
var consLoc = document.getElementById('tcg_cons_location');
var consEmp = document.getElementById('tcg_cons_employee');
var consTile = document.getElementById('tcg_consignment_tile');

function updateConsignmentTile() {
    if (!consignmentEnabled) {
        consTile.classList.add('tcg-action-tile-disabled');
        consTile.href = '#';
        return;
    }
    var c = consCateg.value;
    var l = consLoc.value;
    var p = consPartnerIdField.value;
    var e = consEmp.value;
    if (c && l && p && e) {
        consTile.classList.remove('tcg-action-tile-disabled');
        consTile.href = '/web#action=supertcg_products.action_tcg_card_form'
            + '&categ_id=' + c
            + '&location_id=' + l
            + '&consignment_mode=1'
            + '&consignment_partner_id=' + p
            + '&consignment_partner_name=' + encodeURIComponent(document.getElementById('tcg_cons_partner_selected_name').textContent)
            + '&employee_id=' + e
            + '&employee_name=' + encodeURIComponent(consEmp.options[consEmp.selectedIndex].text);
    } else {
        consTile.classList.add('tcg-action-tile-disabled');
        consTile.href = '#';
    }
}
consCateg.addEventListener('change', updateConsignmentTile);
consLoc.addEventListener('change', updateConsignmentTile);
consEmp.addEventListener('change', updateConsignmentTile);

/* ===== Recent Additions Log ===== */
var logCurrentPage = 1;
var logPageSize = 20;

function renderLogPagination(page, pageCount, total) {
    var container = document.getElementById('tcg_log_pagination');
    container.innerHTML = '';
    if (pageCount == 1) return;
    var prevBtn = document.createElement('button');
    prevBtn.className = 'tcg-log-page-btn';
    prevBtn.textContent = 'Prev';
    prevBtn.disabled = page == 1;
    prevBtn.onclick = function() { loadRecentAdditions(page - 1); };
    container.appendChild(prevBtn);
    var info = document.createElement('span');
    info.className = 'tcg-page-info';
    info.textContent = 'Page ' + page + ' of ' + pageCount + ' (' + total + ' items)';
    container.appendChild(info);
    var nextBtn = document.createElement('button');
    nextBtn.className = 'tcg-log-page-btn';
    nextBtn.textContent = 'Next';
    nextBtn.disabled = page >= pageCount;
    nextBtn.onclick = function() { loadRecentAdditions(page + 1); };
    container.appendChild(nextBtn);
}

function loadRecentAdditions(page) {
    page = page || 1;
    logCurrentPage = page;
    rpc('/tcg/get_recent_additions', {page: page, limit: logPageSize}).then(function(data) {
        var section = document.getElementById('tcg_log_section');
        var list = document.getElementById('tcg_log_list');
        var results = data.entries || [];
        if (!results || results.length === 0) { section.style.display = 'none'; return; }
        section.style.display = 'block';
        list.innerHTML = '';
        results.forEach(function(r) {
            var row = document.createElement('div');
            row.className = 'tcg-log-item';
            var badgesWrap = document.createElement('div');
            badgesWrap.className = 'tcg-log-badges';
            if (r.has_stock && r.stock_url) {
                var stockBadge = document.createElement('a');
                stockBadge.href = r.stock_url;
                stockBadge.target = '_blank';
                stockBadge.className = 'tcg-log-badge stock';
                stockBadge.textContent = 'Stock';
                badgesWrap.appendChild(stockBadge);
            }
            if (r.has_consignment && r.consignment_url) {
                var consBadge = document.createElement('a');
                consBadge.href = r.consignment_url;
                consBadge.target = '_blank';
                consBadge.className = 'tcg-log-badge consignment';
                consBadge.textContent = 'Consignment';
                badgesWrap.appendChild(consBadge);
            }
            row.appendChild(badgesWrap);
            var info = document.createElement('div');
            info.className = 'tcg-log-info';
            var nameEl = document.createElement('div');
            nameEl.className = 'tcg-log-name';
            nameEl.textContent = r.name;
            info.appendChild(nameEl);
            var details = [];
            if (r.employee_name) details.push(r.employee_name);
            if (r.category) details.push(r.category);
            if (r.price > 0) details.push('€ ' + r.price.toFixed(2));
            if (r.partner_name) details.push(r.partner_name);
            var detailEl = document.createElement('div');
            detailEl.className = 'tcg-log-detail';
            detailEl.textContent = details.join(' • ');
            info.appendChild(detailEl);
            var dateEl = document.createElement('div');
            dateEl.className = 'tcg-log-date';
            dateEl.textContent = r.date ? r.date.substring(0, 16).replace('T', ' ') : '';
            info.appendChild(dateEl);
            row.appendChild(info);
            list.appendChild(row);
        });
        renderLogPagination(data.page, data.page_count, data.total);
    });
}

var initialMode = "";
if (initialMode === 'stock') {
    showStockForm();
} else if (initialMode === 'consignment') {
    showConsignmentForm();
} else {
    loadRecentAdditions();
}
